// Owned metadata records use actual reservation/observation contracts. / 自有元数据记录使用实际预留/观察合同。
import {historyFixture} from './business-history.ts';import {GraphMetadata} from '../../src/runtime/graph-metadata.ts';import {PlanningLedger} from '../../src/runtime/planning-ledger.ts';import {hash} from '../../src/runtime/contracts.ts';
export async function metadataFixture(){const f=await historyFixture(),metadata=new GraphMetadata(f.db,()=>f.state.now);return {...f,metadata};}
export async function seedMetadataPlanning(f:any,count=3,ties=false){const ledger=new PlanningLedger(f.db,()=>f.state.now),c=await ledger.configuration(f.actors.it);await ledger.configure(f.actors.it,{expectedVersion:c.version,enabled:true,identitySha256:c.identity_sha256,maxCalls:180,maxOutputTokens:64,outputTokenBudget:11520,timeoutMs:1000,ttlSeconds:300,configurationAcknowledged:true});const rows=[];
 for(let i=0;i<count;i++){const r=await ledger.reserve(f.actors.it,{expectedConfigurationVersion:c.version+1,idempotencyKey:'metadata-'+i,goal:'PRIVATE_GOAL_<script>not-a-list</script>',context:{privateSource:'PRIVATE_CONTEXT'}});await ledger.complete(f.actors.it.enterpriseId,r.id,r.dispatch!.leaseId,{state:'completed',output:{kind:'need_input',questions:['PRIVATE_MODEL_OUTPUT'],privateReceipt:'PRIVATE_RECEIPT'},reportedUsage:{inputTokens:10,outputTokens:20,totalTokens:30}});const timestamp='2026-10-01T00:00:00.'+String(ties?1:i+1).padStart(6,'0')+'Z';await f.db.query('UPDATE planning_candidate SET created_at=$1 WHERE id=$2',[timestamp,r.id]);rows.push({id:r.id,createdAt:timestamp});}return rows;}
export async function seedOtherMetadataBusiness(f:any){const prepared=await f.policy.build(f.actors.executive,f.selection),r=await f.ledger.reserve(f.actors.executive,{...f.input,idempotencyKey:'executive-analysis',contextHash:prepared.contextHash});await f.results.publish(f.actors.executive,r.id,r.dispatch!.leaseId,f.selection,f.wire,{inputTokens:10,outputTokens:20,totalTokens:30});const observation=await f.observations.create(f.actors.executive,{runId:f.run.runId,actionId:f.action.id,resultHash:hash(f.action.result),idempotencyKey:'executive-observation',observationAcknowledged:true});const run=await f.graph.create(f.actors.executive,f.plan.id,{approvalId:f.approval.id,idempotencyKey:'executive-run'});return {analysisId:r.id,observationId:observation.id,runId:run.runId};}

// Unsupported PostgreSQL year zero must fail before SQL. / PostgreSQL不支持的0年必须在SQL前拒绝。
export function yearZeroMetadataCursor(actor:any){return Buffer.from(JSON.stringify({format:'enterprise-brain.metadata-cursor/1',kind:'planning_candidates',enterpriseId:actor.enterpriseId,principalId:actor.id,role:actor.role,authorizationVersion:actor.authorizationVersion,position:{createdAt:'0000-01-01T00:00:00.000000Z',id:'ffffffff-ffff-4fff-8fff-ffffffffffff'}})).toString('base64url');}
